package com.dreamcore.workspace;
import com.dreamcore.workspace.retention.*;import com.dreamcore.workspace.identity.IdentityException;import com.dreamcore.workspace.material.*;
import java.net.*;import java.net.http.*;import java.time.*;import java.util.*;import java.util.concurrent.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.web.server.LocalServerPort;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.mock.web.MockMultipartFile;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.test.context.bean.override.mockito.MockitoBean;import tools.jackson.databind.json.JsonMapper;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"dreamcore.exports.worker-enabled=false","dreamcore.tasks.agent-mode=off","dreamcore.tasks.enabled=false","dreamcore.lifecycle.worker-enabled=false"})
class RetentionIntegrationTest {
 @Autowired JdbcTemplate db;@Autowired RetentionService service;@Autowired MaterialService materials;@Autowired PasswordEncoder passwords;@MockitoBean RetentionClock clock;@LocalServerPort int port;
 UUID tenant,admin,operator,employee,other,space,hidden,personal;final JsonMapper json=new JsonMapper();final Instant start=Instant.parse("2026-10-01T10:00:00Z");final String password="synthetic-retention-password";
 @BeforeEach void fixture(){when(clock.now()).thenReturn(start);tenant=UUID.randomUUID();admin=UUID.randomUUID();operator=UUID.randomUUID();employee=UUID.randomUUID();other=UUID.randomUUID();space=UUID.randomUUID();hidden=UUID.randomUUID();personal=UUID.randomUUID();db.update("INSERT INTO tenants(id,name) VALUES (?,'合成生命周期企业')",tenant);String hashed=passwords.encode(password);for(UUID a:List.of(admin,operator,employee)){db.update("INSERT INTO accounts(id,email,display_name,password_hash) VALUES (?,?,?,?)",a,email(a),a.equals(employee)?"待离职合成员工":"合成负责人",hashed);db.update("INSERT INTO tenant_memberships(tenant_id,account_id,role) VALUES (?,?,?)",tenant,a,a.equals(admin)?"TENANT_ADMIN":"MEMBER");}db.update("INSERT INTO tenants(id,name) VALUES (?,'其他企业')",other);
 db.update("INSERT INTO workspaces(id,tenant_id,owner_id,name,kind) VALUES (?,?,?,'已授权共享空间','SHARED'),(?,?,?,'不可见共享空间','SHARED'),(?,?,?,'私人空间','PERSONAL')",space,tenant,employee,hidden,tenant,employee,personal,tenant,employee);db.update("INSERT INTO workspace_members(tenant_id,workspace_id,account_id,can_maintain) VALUES (?,?,?,true),(?,?,?,true),(?,?,?,true)",tenant,space,operator,tenant,space,employee,tenant,hidden,employee);grant(operator,"MEMBER_OFFBOARD");grant(operator,"TENANT_EXIT");}
 String email(UUID id){return "retention-"+id+"@example.test";}
 void grant(UUID actor,String cap){db.update("INSERT INTO governance_capabilities(tenant_id,account_id,capability,granted_by) VALUES (?,?,?,?) ON CONFLICT DO NOTHING",tenant,actor,cap,admin);}
 RetentionService.Case create(String kind){return service.create(operator,tenant,UUID.randomUUID(),kind,kind.equals("MEMBER_OFFBOARD")?employee:null,"合成准备记录",List.of(space));}
 RetentionService.Case assess(RetentionService.Case c){return service.command(operator,tenant,c.summary().id(),UUID.randomUUID(),c.summary().revision(),"ASSESS",null);}
 @Test void policiesHaveHonestCurrentEnforcementAndAdminCannotImplicitlyOffboard(){var catalogue=service.catalogue(admin,tenant);assertTrue(catalogue.canConfigure());assertFalse(catalogue.canOffboard());assertFalse(catalogue.canExit());assertEquals(13,catalogue.items().size());assertEquals("OBJECT_AND_MATERIAL_WINDOW",catalogue.items().stream().filter(p->p.definition().key().equals("TRASH")).findFirst().orElseThrow().definition().currentEnforcement());assertEquals(403,assertThrows(IdentityException.class,()->service.create(admin,tenant,UUID.randomUUID(),"TENANT_EXIT",null,"不能默认全局",List.of())).status);assertEquals(403,assertThrows(IdentityException.class,()->service.configure(operator,tenant,"TRASH",UUID.randomUUID(),0,20,"没有配置权限")).status);}
 @Test void fixedAnchorPreservesOldDeadlineAcrossPolicyChangeAndReadDoesNotRenew(){var old=service.resolveDeadline(tenant,"TRASH",start.minusSeconds(1));var p=service.configure(admin,tenant,"TRASH",UUID.randomUUID(),0,10,"缩短未来新回收对象");assertEquals(1,p.revision());assertEquals(start,p.effectiveAt());assertEquals(old,service.resolveDeadline(tenant,"TRASH",start.minusSeconds(1)));var next=service.resolveDeadline(tenant,"TRASH",start);assertEquals(start.plus(Duration.ofDays(10)),next.dueAt());assertEquals(1,next.policyRevision());when(clock.now()).thenReturn(start.plus(Duration.ofDays(20)));assertEquals(next,service.resolveDeadline(tenant,"TRASH",start));assertEquals(0,db.queryForObject("SELECT count(*) FROM content_cleanup_jobs WHERE tenant_id=?",Integer.class,tenant));}
 @Test void policyReplayIsExactAndHistoryIsBounded(){UUID key=UUID.randomUUID();var one=service.configure(admin,tenant,"RAW_FEEDBACK",key,0,100,"未来反馈版本");when(clock.now()).thenReturn(start.plusSeconds(10));service.configure(admin,tenant,"RAW_FEEDBACK",UUID.randomUUID(),1,200,"之后调整");assertEquals(one,service.configure(admin,tenant,"RAW_FEEDBACK",key,0,100,"未来反馈版本"));assertEquals("IDEMPOTENCY_CONFLICT",assertThrows(IdentityException.class,()->service.configure(admin,tenant,"RAW_FEEDBACK",key,0,101,"未来反馈版本")).code);var h=service.policyHistory(admin,tenant,"RAW_FEEDBACK",0,1);assertTrue(h.hasMore());assertEquals(2,h.items().getFirst().revision());assertEquals("RETENTION_REVISION_CONFLICT",assertThrows(IdentityException.class,()->service.configure(admin,tenant,"RAW_FEEDBACK",UUID.randomUUID(),0,50,"过时版本")).code);assertThrows(IdentityException.class,()->service.configure(admin,tenant,"EXPORT_PACKAGE",UUID.randomUUID(),0,8,"超限"));assertThrows(IdentityException.class,()->service.configure(admin,tenant,"FORMAL_CONTENT",UUID.randomUUID(),0,30,"不能按访问时间删正式内容"));}
 @Test void adminExitCapabilityDoesNotInventSharedOrPrivateReadRights(){grant(admin,"TENANT_EXIT");assertTrue(service.options(admin,tenant,"TENANT_EXIT",0,0,20).spaces().isEmpty());assertThrows(IdentityException.class,()->service.create(admin,tenant,UUID.randomUUID(),"TENANT_EXIT",null,"不可读",List.of(space)));assertThrows(IdentityException.class,()->service.create(operator,tenant,UUID.randomUUID(),"TENANT_EXIT",null,"私人不迁移",List.of(personal)));assertThrows(IdentityException.class,()->service.create(operator,tenant,UUID.randomUUID(),"TENANT_EXIT",null,"隐藏空间",List.of(hidden)));assertThrows(IdentityException.class,()->service.create(operator,tenant,UUID.randomUUID(),"MEMBER_OFFBOARD",UUID.randomUUID(),"不属于本企业",List.of()));}
 @Test void preparationAndAllManualChecksCannotDisableAccessOrClaimMigration(){var c=create("MEMBER_OFFBOARD");var checks=c.checkDefinitions().stream().map(v->new RetentionService.Check(v.key(),"CONFIRMED")).toList();c=service.command(operator,tenant,c.summary().id(),UUID.randomUUID(),1,"CHECK",checks);var done=assess(c);assertEquals("ASSESSED",done.summary().state());assertEquals("PREPARATION_ONLY",done.executionState());assertFalse(done.assessment().executionEnabled());assertFalse(done.assessment().completeMigration());assertEquals("ACTIVE",done.targetStatus());assertEquals("ACTIVE",db.queryForObject("SELECT status FROM tenants WHERE id=?",String.class,tenant));assertTrue(done.assessment().blockers().contains("EXPLICIT_EXECUTION_REQUIRED"));assertFalse(done.assessment().blockers().contains("MANUAL_CHECKS_INCOMPLETE"));assertEquals(0,db.queryForObject("SELECT count(*) FROM content_cleanup_jobs WHERE tenant_id=?",Integer.class,tenant));assertThrows(IdentityException.class,()->service.command(operator,tenant,done.summary().id(),UUID.randomUUID(),done.summary().revision(),"EXECUTE",null));}
 @Test void assessmentIsExactScopedMetadataAndNeverPrivateText(){materials.upload(employee,tenant,space,null,null,null,UUID.randomUUID(),new MockMultipartFile("file","敏感原件名.txt","text/plain","源正文不得出现在清单".getBytes()));materials.upload(employee,tenant,personal,null,null,null,UUID.randomUUID(),new MockMultipartFile("file","私人文件.txt","text/plain","私人正文".getBytes()));var result=assess(create("TENANT_EXIT"));assertEquals(1,result.assessment().scopes().size());var scope=result.assessment().scopes().getFirst();assertEquals(1,scope.groups().getFirst().count());assertNull(scope.groups().getLast().count());assertEquals("SINGLE_ITEM_DOWNLOAD",scope.groups().getFirst().exportSupport());String serialized=json.writeValueAsString(result);assertFalse(serialized.contains("敏感原件名"));assertFalse(serialized.contains("私人文件"));assertFalse(serialized.contains("源正文不得"));assertFalse(serialized.contains(hidden.toString()));assertEquals("BULK_CAPABILITY_REQUIRED",scope.groups().stream().filter(g->g.key().equals("ENTERPRISE_RESULTS")).findFirst().orElseThrow().exportSupport());}
 @Test void historicalAssessmentIsHiddenImmediatelyWhenWorkspaceGrantIsLost(){var result=assess(create("TENANT_EXIT"));UUID id=result.summary().id();db.update("DELETE FROM workspace_members WHERE tenant_id=? AND workspace_id=? AND account_id=?",tenant,space,operator);var hiddenResult=service.get(operator,tenant,id,2);assertTrue(hiddenResult.selectedScopes().isEmpty());assertTrue(hiddenResult.assessment().scopes().isEmpty());assertEquals(1,hiddenResult.restrictedScopeCount());assertEquals(1,hiddenResult.assessment().restrictedScopeCount());assertFalse(json.writeValueAsString(hiddenResult).contains("已授权共享空间"));assertThrows(IdentityException.class,()->assess(hiddenResult));var cancel=service.command(operator,tenant,id,UUID.randomUUID(),2,"CANCEL",null);assertEquals("CANCELLED",cancel.summary().state());}
 @Test void actualCleanupReceiptsAreSeparateFromBackupAndSnapshotTime(){UUID job=UUID.randomUUID();db.update("INSERT INTO content_cleanup_jobs(id,tenant_id,workspace_id,object_kind,object_id,state,attempts,error_code) VALUES (?,?,?,'MATERIAL',?,'FAILED',2,'OBJECT_STORE_UNAVAILABLE')",job,tenant,space,UUID.randomUUID());var result=assess(create("TENANT_EXIT"));var receipt=result.assessment().scopes().getFirst().cleanup().getFirst();assertEquals("FAILED",receipt.state());assertNull(receipt.completedAt());assertEquals("NOT_COVERED_BY_ONLINE_CLEANUP",receipt.backupState());db.update("UPDATE content_cleanup_jobs SET state='COMPLETE',completed_at=now() WHERE id=?",job);assertEquals("FAILED",service.get(operator,tenant,result.summary().id(),2).assessment().scopes().getFirst().cleanup().getFirst().state());var refreshed=assess(result);assertEquals("COMPLETE",refreshed.assessment().scopes().getFirst().cleanup().getFirst().state());assertEquals(start,refreshed.assessment().assessedAt());}
 @Test void caseReplayConcurrencyRevisionAndCancellationAreReal()throws Exception{UUID key=UUID.randomUUID();try(var pool=Executors.newFixedThreadPool(2)){var calls=pool.invokeAll(List.<Callable<RetentionService.Case>>of(()->service.create(operator,tenant,key,"TENANT_EXIT",null,"并发准备",List.of(space)),()->service.create(operator,tenant,key,"TENANT_EXIT",null,"并发准备",List.of(space))));assertEquals(calls.get(0).get().summary().id(),calls.get(1).get().summary().id());}assertEquals(1,service.list(operator,tenant,0,20).items().size());var c=service.get(operator,tenant,service.list(operator,tenant,0,20).items().getFirst().id(),null);UUID action=UUID.randomUUID();var next=service.command(operator,tenant,c.summary().id(),action,1,"ASSESS",null);assertEquals(next,service.command(operator,tenant,c.summary().id(),action,1,"ASSESS",null));assertThrows(IdentityException.class,()->service.command(operator,tenant,c.summary().id(),UUID.randomUUID(),1,"CANCEL",null));var cancelled=service.command(operator,tenant,c.summary().id(),UUID.randomUUID(),2,"CANCEL",null);assertThrows(IdentityException.class,()->assess(cancelled));assertEquals(3,service.history(operator,tenant,c.summary().id(),0,20).items().size());}
 @Test void revocationAndOtherTenantCannotReadPreparationHistory(){var c=create("TENANT_EXIT");assertThrows(IdentityException.class,()->service.get(operator,other,c.summary().id(),null));db.update("DELETE FROM governance_capabilities WHERE tenant_id=? AND account_id=? AND capability='TENANT_EXIT'",tenant,operator);assertThrows(IdentityException.class,()->service.get(operator,tenant,c.summary().id(),null));assertThrows(IdentityException.class,()->service.history(operator,tenant,c.summary().id(),0,20));assertTrue(service.list(operator,tenant,0,20).items().isEmpty());}
 @Test void unsupportedEmptyScopeDoesNotBecomeCompleteAndPagesAreBounded(){var c=service.create(operator,tenant,UUID.randomUUID(),"TENANT_EXIT",null,"无获权空间",List.of());assertTrue(assess(c).assessment().blockers().contains("NO_AUTHORIZED_SHARED_SCOPE_SELECTED"));create("TENANT_EXIT");assertTrue(service.list(operator,tenant,0,1).hasMore());assertEquals(1,service.list(operator,tenant,1,1).items().size());assertThrows(IdentityException.class,()->service.list(operator,tenant,0,51));}
 final class Client{final HttpClient http=HttpClient.newBuilder().cookieHandler(new CookieManager(null,CookiePolicy.ACCEPT_ALL)).build();HttpResponse<byte[]> send(String method,String path,Object body,boolean csrf)throws Exception{var r=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+path)).header("Content-Type","application/json");if(csrf){var c=json.readTree(send("GET","/api/v1/auth/csrf",null,false).body());r.header(c.get("headerName").asString(),c.get("token").asString());}return http.send(r.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body))).build(),HttpResponse.BodyHandlers.ofByteArray());}}
 @Test void realHttpUsesNoStoreAnd409VersionContract()throws Exception{var c=create("TENANT_EXIT");var client=new Client();assertEquals(200,client.send("POST","/api/v1/auth/login",Map.of("email",email(operator),"password",password),true).statusCode());String root="/api/v1/tenants/"+tenant+"/retention/cases/"+c.summary().id();var read=client.send("GET",root,null,false);assertEquals(200,read.statusCode());assertTrue(read.headers().firstValue("cache-control").orElse("").contains("no-store"));var stale=client.send("POST",root,Map.of("requestId",UUID.randomUUID(),"expectedRevision",99,"action","ASSESS"),true);assertEquals(409,stale.statusCode());assertEquals("RETENTION_REVISION_CONFLICT",json.readTree(stale.body()).get("code").asString());assertEquals("1.0",json.readTree(stale.body()).get("contractVersion").asString());var execution=client.send("POST",root,Map.of("requestId",UUID.randomUUID(),"expectedRevision",1,"action","EXECUTE"),true);assertEquals(400,execution.statusCode());assertEquals("ACTIVE",db.queryForObject("SELECT status FROM tenants WHERE id=?",String.class,tenant));}
}
